# ==============================================================================# 045_RULE_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# RULE TABLE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS rule_engine(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    rule_name TEXT,    source_decision TEXT,    action TEXT,    priority TEXT,    status TEXT,    executed INTEGER DEFAULT 0)""")conn.commit()# ==============================================================================# READ OPEN AI DECISIONS# ==============================================================================cur.execute("""SELECTid,decision,severity,statusFROM ai_decisionsWHERE status='OPEN'ORDER BY id""")decisions = cur.fetchall()rules_created = 0for decision in decisions:    rule = None    if decision["decision"] == "SYSTEM_STABLE":        rule = (            "KEEP_SYSTEM_RUNNING",            decision["decision"],            "NO_ACTION",            "LOW",            "READY"        )    elif decision["decision"] == "SYSTEM_DEGRADED":        rule = (            "RUN_HEALTH_CHECK",            decision["decision"],            "EXECUTE_HEALTH_ENGINE",            "CRITICAL",            "READY"        )    elif decision["decision"] == "COMMAND_QUEUE_PENDING":        rule = (            "PROCESS_COMMAND_QUEUE",            decision["decision"],            "EXECUTE_COMMAND_PROCESSOR",            "HIGH",            "READY"        )    elif decision["decision"] == "TASK_QUEUE_PENDING":        rule = (            "PROCESS_TASK_QUEUE",            decision["decision"],            "EXECUTE_TASK_EXECUTOR",            "HIGH",            "READY"        )    elif decision["decision"] == "ALL_CORE_SERVICES_AVAILABLE":        rule = (            "SYSTEM_READY",            decision["decision"],            "ENABLE_ORCHESTRATOR",            "NORMAL",            "READY"        )    elif decision["decision"] == "SCHEDULER_ACTIVE":        rule = (            "MONITOR_SCHEDULER",            decision["decision"],            "KEEP_SCHEDULER_RUNNING",            "NORMAL",            "READY"        )    else:        continue    cur.execute("""    SELECT id    FROM rule_engine    WHERE        rule_name=?        AND source_decision=?    """,(        rule[0],        rule[1]    ))    if cur.fetchone() is None:        cur.execute("""        INSERT INTO rule_engine(            created_at,            rule_name,            source_decision,            action,            priority,            status        )        VALUES(?,?,?,?,?,?)        """,(            datetime.now().isoformat(),            rule[0],            rule[1],            rule[2],            rule[3],            rule[4]        ))        rules_created += 1conn.commit()# ==============================================================================# OUTPUT# ==============================================================================print("="*80)print("RULE ENGINE")print("="*80)cur.execute("""SELECTrule_name,action,priority,statusFROM rule_engineORDER BYCASE priorityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'NORMAL' THEN 3WHEN 'LOW' THEN 4END,id""")rows = cur.fetchall()for row in rows:    print(        f"{row['priority']:<10}"        f"{row['rule_name']:<28}"        f"{row['action']:<30}"        f"{row['status']}"    )print("="*80)print("NOVAS REGRAS :", rules_created)cur.execute("SELECT COUNT(*) FROM rule_engine")print("TOTAL REGRAS :", cur.fetchone()[0])print("="*80)conn.close()

